prelude_js:
// 行为克隆的误差累积：IID 监督学习给 εT，MDP 里一次错就离开专家分布，
// 界变成 ε·T(T+1)/2。ε=0.01 时：T=10 放大 5.5 倍、T=30 放大 15.5、T=100 放大 50.5、
// T=1000 放大 500.5 —— 放大倍数本身随 T 线性增长。数字由独立脚本核算。
function bcSup(eps,T){return eps*T;}
function bcMDP(eps,T){return eps*T*(T+1)/2;}
function bcAmp(T){return (T+1)/2;}

